parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "headline": {
      "type": "string",
      "description": "Short bold headline with one relevant emoji"
    },
    "post": {
      "type": "string",
      "description": "Full LinkedIn post body, 150-350 words"
    },
    "images": {
      "type": "array",
      "description": "Array of image objects. Empty array if no suitable images found.",
      "items": {
        "type": "object",
        "properties": {
          "url": { "type": "string" },
          "purpose": { "type": "string" }
        },
        "required": ["url"]
      }
    },
    "hashtags": {
      "type": "array",
      "description": "3-5 relevant hashtags",
      "items": { "type": "string" }
    }
  },
  "required": ["headline", "post", "images", "hashtags"]
}
